// Contenido del grado 11° (Estándares Básicos de Competencias en Lenguaje, MEN 2006; DBA de Lenguaje v2, MEN 2016)
import type { Grade } from './types';
const grade: Grade =
{id:'g11',n:11,title:'Literatura universal, argumentación y Saber 11',desc:'Temas universales, argumentar con rigor y prepararse para la prueba de Lectura Crítica.',units:[
{id:'g11u1',title:'Literatura universal',desc:'Clásicos, vanguardias y el lector que elige.',lessons:[
 {id:'g11u1l1',title:'Los clásicos y los temas universales',time:50,std:'Analizo crítica y creativamente diferentes manifestaciones literarias del contexto universal.',dba:'DBA 4 (11°): analiza crítica y creativamente diferentes manifestaciones literarias del contexto universal.',
  body:['Un <b>clásico</b> es una obra que se sigue leyendo siglos después de escrita. Italo Calvino dijo que es un libro que "nunca termina de decir lo que tiene que decir". No pierde sentido cuando cambia la época: cada generación lo relee con preguntas nuevas.',
   'Los clásicos duran porque tratan <b>temas universales</b>: preocupaciones que comparten todos los seres humanos, en cualquier época o país. Un asunto local y pasajero, como el precio del pasaje de bus, no es universal. Cuatro grandes temas: <b>poder</b>, <b>amor</b>, <b>muerte</b> y <b>destino</b>.',
   'El <b>poder</b> y la ambición mueven <i>Macbeth</i>, de William Shakespeare: un noble asesina al rey Duncan para quedarse con la corona. El <b>amor</b>, muchas veces imposible, une a <i>Romeo y Julieta</i>, también de Shakespeare, contra el odio de sus familias.',
   'La <b>muerte</b> ya aparece en el <i>Poema de Gilgamesh</i>, de Mesopotamia, de hace unos cuatro mil años: el héroe busca la inmortalidad tras ver morir a su amigo Enkidu. Después la retoman Jorge Manrique en sus <i>Coplas</i> y Tolstói en <i>La muerte de Iván Ilich</i>.',
   'El <b>destino</b> es lo que parece fijado de antemano. En <i>Edipo rey</i>, de Sófocles, Edipo huye de lo que anunció el oráculo y termina cumpliéndolo. En <i>La vida es sueño</i>, de Calderón de la Barca, chocan la <b>libertad</b> y el destino.',
   'Otros clásicos: la <i>Odisea</i>, de <b>Homero</b> (el regreso de Ulises); <i>Hamlet</i>, de <b>Shakespeare</b> (la duda y la venganza); <i>Don Quijote</i>, de <b>Cervantes</b> (el ideal frente a la realidad); <i>Crimen y castigo</i>, de <b>Dostoievski</b> (la culpa); <i>La metamorfosis</i>, de <b>Kafka</b> (la deshumanización).',
   'En <b>Antígona</b> (Sófocles, siglo V a. C.), el rey Creonte prohíbe enterrar a Polinices. Su hermana Antígona lo entierra aunque la castiguen. Ella obedece a su <b>conciencia</b> y al deber con los muertos; Creonte, a la <b>ley del poder</b> que él mismo dictó.'],
  bites:[{ej:'Seguimos leyendo a Shakespeare, que escribió hace más de 400 años, y sus historias se vuelven películas y series.',check:{q:'¿Qué hace que una obra sea un clásico?',o:['Que se siga leyendo y diga cosas nuevas en cada época','Que sea muy corta','Que esté de moda este año'],a:0,e:'Un clásico sigue hablándole a cada generación.'}},
   {ej:'Una canción de despecho de hoy y <i>Romeo y Julieta</i> hablan del mismo tema: el amor.',ojo:'Universal no es "famoso": es lo que preocupa a cualquier ser humano, sea de Bogotá o de Tokio.',check:{q:'¿Cuál es un tema universal?',o:['El precio del pasaje de bus','La muerte','El horario de un almacén'],a:1,e:'La muerte le preocupa a todo ser humano, en cualquier época.'}},
   {ej:'Más poder: en <i>El otoño del patriarca</i>, de García Márquez, un dictador se aferra al mando durante décadas. Más amor: Efraín y María en <i>María</i>, de Jorge Isaacs, y Florentino y Fermina en <i>El amor en los tiempos del cólera</i>.',check:{q:'Macbeth mata al rey para quedarse con la corona. ¿Qué tema domina?',o:['El poder','El amor'],a:0,e:'La ambición de mandar es el tema del poder.'}},
   {ej:'Manrique escribió: "nuestras vidas son los ríos que van a dar en la mar". Todos los ríos terminan en el mar, como todas las vidas en la muerte.',ojo:'Gilgamesh es de las obras más antiguas que se conocen: la muerte preocupa a la humanidad desde siempre.'},
   {ej:'En <i>Cien años de soledad</i>, los Buendía repiten nombres y errores como si su familia estuviera condenada de antemano.',ojo:'Truco: si el personaje huye de algo anunciado y aun así le pasa, el tema es el destino.',check:{q:'Edipo huye del oráculo y termina cumpliendo lo anunciado. ¿Qué tema es?',o:['El amor','El destino','El poder'],a:1,e:'Lo que estaba anunciado se cumple: es el destino.'}},
   {ej:'<i>Cien años de soledad</i> es de <b>Gabriel García Márquez</b>. En <i>La metamorfosis</i>, Gregorio Samsa amanece convertido en insecto y su familia lo rechaza.',check:{q:'¿Quién escribió <i>Don Quijote</i>?',o:['Miguel de Cervantes','Franz Kafka','Homero'],a:0,e:'Cervantes escribió el Quijote: el ideal frente a la realidad.'}},
   {ej:'En Colombia, Tramaluna Teatro montó <i>Antígonas, tribunal de mujeres</i> (2014): mujeres víctimas del conflicto piden verdad y justicia, como Antígona pidió enterrar a su hermano.',ojo:'El conflicto de Antígona es conciencia contra ley del poder, no un amor imposible.',check:{q:'¿A qué obedece Antígona?',o:['A la ley de Creonte','A su conciencia y al deber con los muertos'],a:1,e:'Antígona desobedece al rey por su conciencia.'}}],
  key:'Un clásico sigue hablándonos porque trata temas universales: el poder, el amor, la muerte y el destino.',
  co:'En "Antígonas, tribunal de mujeres" (Tramaluna Teatro, 2014), mujeres víctimas del conflicto armado suben al escenario junto a actrices para exigir verdad y justicia, como Antígona exigió el derecho a enterrar a su hermano.',
  act:{type:'match',prompt:'Une cada obra con su tema o su conflicto.',pairs:[['Macbeth','El poder: matar al rey para tener la corona'],['Romeo y Julieta','El amor contra el odio de dos familias'],['Poema de Gilgamesh','La muerte y la búsqueda de la inmortalidad'],['Edipo rey','El destino anunciado por el oráculo'],['La vida es sueño','La libertad frente al destino'],['Antígona','La conciencia frente a la ley del poder'],['El otoño del patriarca','Un dictador que no suelta el mando'],['La metamorfosis','Un hombre convertido en insecto y rechazado']],e:'Cada clásico gira alrededor de un tema universal que organiza su conflicto.'},
  quiz:[{q:'Según la lección, ¿qué es un tema universal?',o:['Un tema que solo aparece en la literatura europea','Una preocupación humana que aparece en todas las épocas y culturas','Un tema que está de moda en las redes sociales','El resumen del argumento de una obra famosa'],a:1,e:'Los temas universales (poder, amor, muerte, destino) atraviesan épocas y culturas.',lv:'L'},
   {q:'Antígona entierra a su hermano aunque Creonte lo prohibió y sabe que la castigarán. ¿Qué conflicto de fondo plantea la obra?',o:['Un amor imposible entre dos jóvenes','La ley del poder frente a la conciencia y el deber con los muertos','La búsqueda de la inmortalidad','Una guerra por un tesoro'],a:1,e:'Antígona obedece a su conciencia y a las leyes no escritas; Creonte, a la ley de la ciudad que él mismo dictó.',lv:'I'},
   {q:'¿Por qué grupos de teatro colombianos han vuelto a montar Antígona con víctimas del conflicto?',o:['Porque es una obra corta y fácil de montar','Porque su conflicto, el derecho a enterrar y llorar a los muertos frente al poder, sigue vivo en el país','Porque las obras griegas no tienen derechos de autor','Porque es la única tragedia que se conserva completa'],a:1,e:'Un clásico se relee desde el presente: la búsqueda de los desaparecidos da un sentido nuevo a la tragedia de Sófocles.',lv:'C'}],
  tip:'Pida a cada grupo que traiga una canción, serie o noticia actual que trate el mismo tema universal de una obra clásica y explique la conexión en dos minutos.'},
 {id:'g11u1l2',title:'Vanguardias y siglo XX',time:50,std:'Identifico en obras de la literatura universal el lenguaje, las características formales, las épocas y escuelas, estilos, tendencias, temáticas, géneros y autores, entre otros aspectos.',dba:'DBA 3 (11°): formula puntos de encuentro entre la literatura y las artes plásticas y visuales.',
  body:['A comienzos del siglo XX, entre fábricas, carros y la Primera Guerra Mundial, nacieron las <b>vanguardias</b>: movimientos que querían romper con la tradición del siglo XIX. Esa tradición era el <b>Romanticismo</b> (<i>María</i>, de Jorge Isaacs, 1867) y el <b>Modernismo</b> (<i>Azul...</i>, de Rubén Darío, 1888).',
   'El <b>futurismo</b> nació con el manifiesto de Filippo Tommaso Marinetti (1909). Celebró la velocidad, las máquinas y hasta la guerra. Dijo que un carro de carreras es más bello que una estatua griega y propuso las "palabras en libertad", sin sintaxis ni puntuación.',
   'El <b>dadaísmo</b> nació en 1916 en el Cabaret Voltaire de Zúrich. Respondió a la guerra con el absurdo y el <b>antiarte</b>. Tristan Tzara enseñó a hacer un poema sacando de una bolsa palabras recortadas de un periódico.',
   'El <b>surrealismo</b> (primer manifiesto de André Breton, 1924) exploró los sueños y el inconsciente. Usó la <b>escritura automática</b> y el <b>cadáver exquisito</b>: un poema escrito entre varios sin ver lo que puso el anterior. Dalí y Magritte pintaron esas imágenes ilógicas.',
   'En Hispanoamérica, Vicente Huidobro propuso el <b>creacionismo</b> y César Vallejo retorció el idioma en <i>Trilce</i> (1922). En Colombia, <b>Los Nuevos</b>, que tomaron su nombre de una revista fundada en Bogotá en 1925, con León de Greiff y Luis Vidales, se burlaron de la poesía solemne.',
   'El <b>nadaísmo</b> lo fundó Gonzalo Arango en Medellín, con su primer manifiesto de 1958. Con poetas como Jotamario Arbeláez, escandalizó con humor, rebeldía y provocación a una sociedad conservadora y religiosa, marcada por la Violencia.',
   'Luego vino el gran siglo latinoamericano: <i>La vorágine</i> (Rivera) y <i>Veinte poemas de amor</i> (Neruda), en 1924; <i>Ficciones</i> (Borges), 1944; <i>Pedro Páramo</i> (Rulfo), 1955; <i>Rayuela</i> (Cortázar), 1963; y <i>Cien años de soledad</i> (García Márquez), 1967, cumbre del <b>boom</b>. En 1982, García Márquez ganó el <b>Nobel</b>.'],
  bites:[{ej:'Es como cuando una banda nueva dice: "no queremos sonar como nuestros papás".',ojo:'Romanticismo y Modernismo son del siglo XIX: son ANTES de las vanguardias, no son vanguardias.',check:{q:'¿Qué querían las vanguardias?',o:['Romper con la tradición','Copiar la poesía del siglo XIX'],a:0,e:'Vanguardia es ir adelante, romper con lo anterior.'}},
   {ej:'Imagina un poema que suena a motor: "¡Rrrum! velocidad acero ¡ya!", sin comas ni puntos.',check:{q:'¿Qué celebraba el futurismo?',o:['La velocidad y las máquinas','Los sueños','El campo tranquilo'],a:0,e:'Marinetti amaba la velocidad, las máquinas y hasta la guerra.'}},
   {ej:'Poema dadá: recorta palabras de una noticia de <i>El Tiempo</i>, mételas en una bolsa y cópialas en el orden en que salgan.',ojo:'Dadá = absurdo y antiarte, como respuesta a la guerra.',check:{q:'¿Dónde nació el dadaísmo?',o:['En el Cabaret Voltaire de Zúrich','En Medellín'],a:0,e:'Nació en Zúrich en 1916.'}},
   {ej:'"Sueño que el reloj se derrite sobre un pez que conversa con mi abuela": eso suena surrealista.',ojo:'Truco: sueños e imágenes sin lógica = surrealismo.'},
   {ej:'León de Greiff jugaba con palabras raras y música en sus versos; Luis Vidales publicó <i>Suenan timbres</i> en 1926.',check:{q:'¿Dónde nació la revista Los Nuevos?',o:['En Bogotá, en 1925','En París, en 1909'],a:0,e:'Los Nuevos fue un grupo colombiano de 1925.'}},
   {ej:'Los nadaístas hacían actos para escandalizar en Medellín y Cali, en plena época de la Violencia.',check:{q:'¿Quién fundó el nadaísmo?',o:['Gonzalo Arango','André Breton','Marinetti'],a:0,e:'Gonzalo Arango lo fundó en Medellín en 1958.'}},
   {ej:'<i>La vorágine</i> es colombiana: cuenta la vida dura de los caucheros en la selva.',ojo:'El orden de los años sirve para la línea de tiempo: 1924, 1944, 1955, 1963, 1967, 1982.',check:{q:'¿Qué obra es la cumbre del boom?',o:['Cien años de soledad','María'],a:0,e:'Cien años de soledad (1967) es la cumbre del boom.'}}],
  key:'Las vanguardias rompen con la tradición: futurismo, dadaísmo y surrealismo en Europa; Los Nuevos y el nadaísmo en Colombia.',
  co:'Luis Vidales publicó "Suenan timbres" en 1926, un libro pionero de la vanguardia colombiana; tres décadas después, los nadaístas como Gonzalo Arango y Jotamario Arbeláez llevaron la provocación a Medellín y Cali.',
  act:{type:'map',kind:'timeline',prompt:'Pon cada tarjeta en su año. Sobran dos que no son vanguardias.',slots:[{label:'1909',a:'Futurismo: manifiesto de Marinetti'},{label:'1916',a:'Dadaísmo: Cabaret Voltaire en Zúrich'},{label:'1922',a:'Trilce, de César Vallejo'},{label:'1924',a:'Surrealismo: primer manifiesto de Breton'},{label:'1925',a:'Los Nuevos: revista en Bogotá'},{label:'1958',a:'Nadaísmo: primer manifiesto de Gonzalo Arango'}],extra:['Romanticismo: María, de Jorge Isaacs','Modernismo: Azul..., de Rubén Darío'],e:'María (1867) y Azul... (1888) son del siglo XIX: el Romanticismo y el Modernismo son anteriores a las vanguardias.'},
  quiz:[{q:'¿Qué movimiento celebró la velocidad, las máquinas y hasta la guerra?',o:['Surrealismo','Futurismo','Dadaísmo','Nadaísmo'],a:1,e:'El manifiesto de Marinetti (1909) exaltó la velocidad, la técnica y la guerra.',lv:'L'},
   {q:'Un poema dice: "Sueño que el reloj se derrite sobre un pez que conversa con mi abuela". ¿A qué vanguardia se parece más?',o:['Futurismo','Surrealismo','Romanticismo','Modernismo'],a:1,e:'Las imágenes oníricas e ilógicas son propias del surrealismo, que buscaba el mundo de los sueños.',lv:'I'},
   {q:'¿Por qué el nadaísmo escandalizó a la Colombia de finales de los años cincuenta?',o:['Porque escribía solo en inglés','Porque desafiaba con humor y provocación los valores de una sociedad conservadora y religiosa','Porque proponía volver a la poesía del Siglo de Oro','Porque defendía las costumbres tradicionales'],a:1,e:'El nadaísmo irrumpió en una sociedad marcada por la Violencia y el conservadurismo, y la provocación fue su arma.',lv:'C'}],
  tip:'Haga un "cadáver exquisito" surrealista: cada estudiante escribe un verso doblando el papel para que el siguiente no lo vea; al final lean el poema completo.'},
 {id:'g11u1l3',title:'El lector que elige',time:50,std:'Comprendo e interpreto textos con actitud crítica y capacidad argumentativa.',dba:'DBA 3 (11°): formula puntos de encuentro entre la literatura y las artes plásticas y visuales.',
  body:['Leer no es solo cumplir con el libro del plan de área. Un <b>lector autónomo</b> elige qué leer, sabe para qué lo lee y cambia de estrategia según el texto.',
   'Para eso sirve un <b>plan lector</b>: una lista de lecturas con propósito, tiempos y lugares. Elegir bien es variar: novela, crónica, poesía, novela gráfica, ensayo. Ojo con el algoritmo de las redes: te muestra lo parecido a lo que ya lees.',
   'Las <b>estrategias</b> se usan en tres momentos: antes, durante y después de leer. <b>Antes</b>: define tu propósito, hojea el libro y predice de qué trata por el título y la contraportada.',
   '<b>Durante</b> la lectura: subraya solo lo esencial, anota al margen y hazte preguntas. Si una palabra desconocida es clave, dedúcela por el contexto o búscala. Lee lejos de distracciones como el celular.',
   'También durante: relee lo difícil y comprueba si entendiste. Un truco: al terminar cada párrafo, di con tus propias palabras lo que acabas de leer.',
   '<b>Después</b> de leer: resume con tus propias palabras, escribe una reseña o conversa sobre lo leído, por ejemplo en un club de lectura.',
   'Un buen lector recorre tres <b>niveles</b>: el <b>literal</b> (qué dice el texto), el <b>inferencial</b> (qué da a entender) y el <b>crítico</b> (qué pienso yo y con qué razones).'],
  bites:[{ej:'Camila solo leía lo que le mandaban en el colegio. Un sábado eligió un libro en BibloRed y no pudo soltarlo.',check:{q:'¿Qué hace un lector autónomo?',o:['Elige qué leer y para qué','Solo lee lo que le mandan'],a:0,e:'El lector autónomo decide qué, para qué y cómo leer.'}},
   {ej:'Plan de Camila: <i>Relato de un náufrago</i> por gusto, una novela gráfica y un libro de poemas; en BibloRed; veinte minutos cada noche.',ojo:'El algoritmo te cierra otros géneros y miradas: busca también lo distinto.',check:{q:'¿Qué riesgo tiene leer solo lo que recomienda el algoritmo?',o:['Que solo te muestre lo parecido a lo que ya lees','Que los libros salgan más caros'],a:0,e:'El algoritmo repite tus gustos y te encierra.'}},
   {ej:'Ves en la portada un bote en el mar y predices: "esto es una historia de supervivencia".',check:{q:'¿Qué se hace ANTES de leer?',o:['Resumir el libro','Definir el propósito y hojear','Escribir una reseña'],a:1,e:'Antes: propósito, hojear y predecir.'}},
   {ej:'Anotas al margen: "¿por qué el náufrago no se rinde?".',ojo:'Si todo está subrayado, nada se destaca: subraya poco.',check:{q:'¿Cuál es buena estrategia durante la lectura?',o:['Subrayar todo','Hacerse preguntas y anotar al margen'],a:1,e:'Preguntar y anotar mantiene activa la lectura.'}},
   {ej:'Laura lee un artículo difícil y, después de cada párrafo, se dice: "o sea, que las abejas se comunican bailando".'},
   {ej:'En un club de lectura de BibloRed, cada joven cuenta qué le gustó y qué no del libro.',check:{q:'Escribir una reseña es una estrategia de…',o:['Antes de leer','Durante la lectura','Después de leer'],a:2,e:'La reseña se hace al terminar.'}},
   {ej:'Literal: "Camila fue a BibloRed". Inferencial: "le empezó a gustar leer". Crítico: "creo que elegir por la portada puede fallar, porque...".',ojo:'El nivel crítico siempre lleva razones, no solo "me gustó".',check:{q:'"¿Qué da a entender el texto?" es el nivel…',o:['Literal','Inferencial','Crítico'],a:1,e:'Inferir es deducir lo que no se dice directamente.'}}],
  key:'Elige con propósito, usa estrategias antes, durante y después, y lee en los tres niveles.',
  co:'BibloRed, la red de bibliotecas públicas de Bogotá, presta libros gratis con la afiliación, tiene grandes sedes como la Virgilio Barco y El Tintal, y organiza clubes de lectura para jóvenes.',
  act:{type:'order',prompt:'Ordena lo que hace Camila con su libro, de antes a después de leer.',items:['Define para qué va a leer: por gusto','Hojea el libro y predice de qué trata por la contraportada','Subraya solo lo esencial y anota preguntas al margen','Relee lo difícil y lo dice con sus propias palabras','Resume el libro con sus propias palabras','Comenta el libro en un club de lectura'],e:'Antes se fija el propósito y se predice; durante se subraya, se pregunta y se comprueba; después se resume y se comparte.'},
  quiz:[{q:'¿Qué estrategia se usa ANTES de leer?',o:['Resumir el texto','Definir el propósito y hojear el texto','Escribir una reseña','Conversar sobre el final'],a:1,e:'Antes de leer se fija el propósito, se hojea y se predice.',lv:'L'},
   {q:'Laura lee un artículo científico difícil y, al terminar cada párrafo, se dice con sus palabras qué acaba de leer. ¿Qué está haciendo?',o:['Una estrategia durante la lectura: revisar su propia comprensión','Una prelectura','Una reseña crítica','Una lectura por gusto sin estrategia'],a:0,e:'Parafrasear mientras se lee es una estrategia de control de la comprensión.',lv:'I'},
   {q:'Un compañero dice: "Solo leo lo que me recomienda el algoritmo de mi red social". ¿Qué riesgo tiene esa forma de elegir?',o:['Ninguno, el algoritmo siempre acierta','Que lea demasiado rápido','Que solo le muestren lo parecido a lo que ya lee y se cierre a otros géneros y miradas','Que los libros le salgan más caros'],a:2,e:'Los algoritmos refuerzan los gustos previos; un lector autónomo busca también lo distinto.',lv:'C'}],
  tip:'Visite con el curso el catálogo en línea de BibloRed o la biblioteca del colegio y pida que cada estudiante arme su plan lector (tres lecturas de géneros distintos, dónde conseguirlas y cuándo leerlas) y reserve el primer libro antes de salir.'}
]},
{id:'g11u2',title:'Argumentar con rigor',desc:'Tipos de argumentos, falacias y el ensayo argumentativo.',lessons:[
 {id:'g11u2l1',title:'Tipos de argumentos',time:50,std:'Produzco textos argumentativos que evidencian mi conocimiento de la lengua y el control sobre el uso que hago de ella en contextos comunicativos orales y escritos.',dba:'DBA 6 y 8 (11°): comprende que los argumentos de sus interlocutores involucran procesos de comprensión, crítica y proposición; produce textos académicos con procedimientos sistemáticos de producción textual.',
  body:['Un <b>argumento</b> es una razón que apoya una <b>tesis</b>, la idea que se defiende. No todos los argumentos funcionan igual: según de dónde saquen su fuerza, hay varios <b>tipos</b>.',
   'El argumento de <b>autoridad</b> cita a un experto o a una institución reconocida ("según el IDEAM..."). El de <b>causa</b> muestra que un hecho produce otro ("como...", "si...").',
   'El de <b>analogía</b> compara con un caso parecido ("es como..."). El de <b>datos</b> usa cifras verificables. El de <b>ejemplo</b> presenta un caso concreto: lo que pasó en un barrio, un colegio o una casa.',
   'Truco para clasificar: pregunta de dónde saca su fuerza la razón. Si está en quién lo dice, es de autoridad, aunque hable de una causa. Si está en una cifra, es de datos, aunque diga de dónde salió.',
   'Un buen texto combina tipos y responde a los <b>contraargumentos</b>, las razones del otro lado. Esa respuesta se llama <b>refutación</b>.',
   'Un argumento pesa si es pertinente, verificable y suficiente. Pesan poco un famoso que opina de salud sin pruebas o un ejemplo aislado. Y una analogía solo convence si los dos casos comparados se parecen de verdad.'],
  bites:[{ej:'Tesis: "Bogotá debe proteger sus páramos". Argumento: "sin páramos, la ciudad se queda sin agua".',check:{q:'¿Qué es la tesis?',o:['La idea que se defiende','Una cifra'],a:0,e:'La tesis es la idea; el argumento, la razón que la apoya.'}},
   {ej:'Autoridad: "Una hidróloga de la Universidad Nacional advierte que...". Causa: "Como llovió menos, los embalses bajaron".',check:{q:'"Si se talan los cerros, las quebradas pierden caudal." ¿Qué tipo es?',o:['De causa','De autoridad'],a:0,e:'Muestra que un hecho produce otro.'}},
   {ej:'Analogía: "El páramo es como una esponja". Datos: "Chingaza aporta cerca del 70 % del agua de Bogotá". Ejemplo: "En mi edificio reutilizamos el agua de la lavadora".',check:{q:'"Gastar agua sin medida es como gastarse el sueldo el primer día." ¿Qué tipo es?',o:['De datos','De analogía','De ejemplo'],a:1,e:'Compara con un caso parecido: "es como".'}},
   {ej:'"Según el IDEAM, El Niño reduce las lluvias": habla de una causa, pero su fuerza está en el IDEAM. Es de autoridad.',ojo:'No te dejes llevar por la palabra "como" o "según": mira dónde está la fuerza.',check:{q:'"Según una encuesta, el 45 % usa el celular seis horas." ¿Dónde está la fuerza?',o:['En la cifra: es de datos','En quién lo dice: es de autoridad'],a:0,e:'La fuerza está en la cifra, aunque diga de dónde salió.'}},
   {ej:'Contraargumento: "la minería da empleo". Refutación: "pero sin agua no hay empleo que aguante".'},
   {ej:'Un influenciador dice que un suplemento cura la ansiedad: fama no es saber de salud.',ojo:'Toda analogía se puede discutir mostrando en qué se diferencian los casos.',check:{q:'¿Por qué pesa poco un famoso que opina de salud?',o:['Porque no es experto y no da pruebas','Porque tiene muchos seguidores'],a:0,e:'La autoridad vale si es experta en el tema y se puede verificar.'}}],
  key:'Autoridad, causa, analogía, datos y ejemplo: cada tipo de argumento apoya la tesis de una manera distinta.',
  co:'Durante el racionamiento de agua de 2024 en Bogotá, el debate público enfrentó argumentos de datos (el nivel del embalse de Chingaza), de causa (el fenómeno de El Niño) y de ejemplo (familias y barrios que lograron ahorrar).',
  act:{type:'classify',prompt:'Tesis: "Bogotá debe cuidar el agua y proteger sus páramos". ¿Qué tipo de argumento es cada razón?',bins:['Autoridad','Causa','Analogía','Datos','Ejemplo'],items:[['Una hidróloga de la Universidad Nacional advierte que sin páramos la ciudad se queda sin agua',0],['Según el IDEAM, el fenómeno de El Niño reduce las lluvias en la región andina',0],['Como llovió menos durante meses, los embalses bajaron a niveles críticos',1],['Si se talan los bosques de los cerros, las quebradas pierden caudal',1],['El páramo funciona como una esponja: guarda el agua y la suelta poco a poco',2],['Gastar agua sin medida es como gastarse el sueldo el primer día del mes',2],['El sistema Chingaza aporta cerca del 70 % del agua que consume Bogotá',3],['Una ducha de diez minutos puede gastar más de 80 litros de agua',3],['En mi edificio, reutilizar el agua de la lavadora bajó el recibo casi a la mitad',4],['Durante el racionamiento, un colegio de Suba instaló llaves ahorradoras y redujo su consumo',4]],e:'Mira de dónde saca su fuerza cada razón: de quién lo dice, de una causa, de una comparación, de una cifra o de un caso concreto.'},
  quiz:[{q:'"Una hidróloga de la Universidad Nacional explica que sin páramos no hay agua para Bogotá." ¿Qué tipo de argumento es?',o:['De analogía','De autoridad','De ejemplo','De causa'],a:1,e:'Se apoya en el conocimiento de una experta en el tema.',lv:'L'},
   {q:'"Prohibir el celular en clase sería como prohibir los lápices porque algunos rayan los pupitres." ¿Qué tipo de argumento es y cuál es su punto débil?',o:['De datos: no tiene cifras','De analogía: solo funciona si los dos casos son realmente parecidos','De autoridad: no cita a nadie','De ejemplo: es un caso real'],a:1,e:'Toda analogía se puede discutir mostrando en qué se diferencian los casos comparados.',lv:'I'},
   {q:'Un influenciador con millones de seguidores asegura que un suplemento cura la ansiedad. ¿Por qué es un argumento de autoridad débil?',o:['Porque tiene demasiados seguidores','Porque su fama no lo convierte en experto en salud y no presenta evidencia','Porque es muy joven','Porque lo dice en un video'],a:1,e:'Una autoridad vale si es experta en el tema del que habla y su afirmación se puede verificar.',lv:'C'}],
  tip:'Dé una tesis polémica del colegio y pida a cada grupo defenderla con un tipo de argumento distinto; al final el curso vota cuál pesó más y por qué.'},
 {id:'g11u2l2',title:'Las falacias',time:50,std:'Expreso respeto por la diversidad cultural y social del mundo contemporáneo, en las situaciones comunicativas en las que intervengo.',dba:'DBA 5 y 7 (11°): comprende que en la relación con los otros deben primar el respeto y la igualdad; participa en discursos orales en los que evalúa la progresión temática, el manejo de la voz y los puntos de vista.',
  body:['Una <b>falacia</b> es un razonamiento que parece válido pero no lo es. Funciona porque apela a las emociones, a la prisa o a los prejuicios. Abunda en debates, campañas y redes sociales.',
   'El <b>ad hominem</b> ("contra la persona", en latín) ataca a quien habla y no a su idea. El <b>hombre de paja</b> deforma lo que dijo el otro para refutarlo más fácil.',
   'El <b>falso dilema</b> reduce todo a dos opciones cuando hay más: "o estás conmigo o contra mí". La <b>generalización apresurada</b> saca una regla general de uno o dos casos.',
   'La <b>apelación a la mayoría</b> dice que algo es cierto porque muchos lo creen o lo comparten. La <b>pendiente resbaladiza</b> anuncia una cadena de desastres sin probar que un paso lleve al siguiente.',
   'La <b>falsa causa</b> supone que, porque una cosa pasó después de otra, la primera la causó. La <b>pregunta compleja</b> da por probada una acusación: "¿ya dejaste de copiarte?".',
   'La <b>apelación a la autoridad</b> cita a un famoso que no es experto en el tema. La <b>apelación a la emoción</b> busca conmover en vez de dar razones. En cambio, un argumento válido se apoya en datos verificables, expertos pertinentes o causas comprobadas.',
   'Detectarlas es un deber ciudadano. Ante una falacia no respondas con otra ni con burlas: nombra el error con calma, muestra por qué no prueba nada y vuelve a la idea en discusión, con respeto por la persona.'],
  bites:[{ej:'En época de elecciones circulan memes que se burlan del físico de un candidato en vez de discutir sus propuestas.',check:{q:'¿Qué es una falacia?',o:['Un razonamiento que parece válido pero no lo es','Un dato comprobado'],a:0,e:'Parece un argumento, pero no prueba nada.'}},
   {ej:'Ad hominem: "¿Qué va a saber ella de comida, si ni hace deporte?". Hombre de paja: "Mi rival quiere que comamos solo lechuga" (ella nunca dijo eso).',ojo:'Truco: el hombre de paja es un muñeco que el rival arma para pegarle fácil.',check:{q:'"No le creas: ni siquiera es buena en matemáticas." ¿Qué falacia es?',o:['Ad hominem','Falso dilema'],a:0,e:'Ataca a la persona, no a su idea.'}},
   {ej:'Falso dilema: "O votan por mí o el colegio seguirá igual de mal". Generalización: "Un gamer faltó a clase: los gamers son vagos".',check:{q:'"Conocí a dos bogotanos groseros: los rolos son maleducados." ¿Qué falacia es?',o:['Generalización apresurada','Pendiente resbaladiza'],a:0,e:'Dos casos no hacen una regla.'}},
   {ej:'Mayoría: "Todos los de once ya me apoyan: por algo será". Pendiente: "Si cambian el menú, prohíben las onces y al final cierran la cafetería".',ojo:'Que algo sea viral no lo vuelve cierto.'},
   {ej:'Falsa causa: "Desde que usas ese buzo perdemos los partidos".',ojo:'Coincidir en el tiempo no es causar.',check:{q:'"Me puse la camiseta de la suerte y ganó Millonarios." ¿Qué falacia es?',o:['Falsa causa','Apelación a la mayoría'],a:0,e:'Una coincidencia no prueba una causa.'}},
   {ej:'Autoridad falsa: un cantante asegura que un té cura el cáncer. Emoción: "Piensa en los niños que llorarán si no me apoyas". Válido: "Según el IDEAM, El Niño reduce las lluvias".',check:{q:'¿Cuál es un argumento válido?',o:['Un futbolista dice que ese banco es el más seguro','El Ministerio de Salud muestra que la vacuna redujo las hospitalizaciones'],a:1,e:'Autoridad pertinente con evidencia: es válido.'}},
   {ej:'"Eso es un ad hominem: hablas de mí, no de la propuesta. Volvamos a la encuesta: el 60 % pidió comida saludable."',check:{q:'Tu rival usa una falacia. ¿Qué haces?',o:['Respondo con otra falacia','Nombro el error con calma y vuelvo a la idea'],a:1,e:'Se desmonta el razonamiento, no a la persona.'}}],
  key:'Una falacia parece un argumento pero no lo es: atacar a la persona, deformar, exagerar o generalizar no prueba nada.',
  co:'En época de elecciones circulan frases como "El que no vota por mí quiere que el país se hunda" (falso dilema) y memes que se burlan del físico de un candidato en vez de discutir sus propuestas (ad hominem).',
  act:{type:'comic',prompt:'Debate para la personería. Completa lo que responden Valentina y la moderadora a cada falacia de Santiago.',panels:[{who:'Santiago',face:'😏',say:'¿Qué va a saber Valentina de comida, si ni siquiera hace deporte?'},{who:'Moderadora',face:'🧐',say:'Santiago, eso es un {{ad hominem|falso dilema|dato}}: atacas a la persona, no su propuesta.'},{who:'Santiago',face:'😏',say:'Valentina quiere que comamos solo lechuga. Además, todos los de once me apoyan.'},{who:'Valentina',face:'🙂',say:'Lo primero es un {{hombre de paja|dato verificable}}: yo no dije eso. Lo segundo es una {{apelación a la mayoría|pendiente resbaladiza}}.'},{who:'Santiago',face:'😠',say:'Si cambian el menú, mañana prohíben las onces y cierran la cafetería. ¡O votan por mí o todo sigue mal!'},{who:'Valentina',face:'🙂',say:'Eso es una {{pendiente resbaladiza|generalización apresurada}} y un {{falso dilema|ad hominem}}. Volvamos a {{los datos|los insultos}}: el 60 % pidió opciones saludables.'}],e:'Ante una falacia se nombra el error con calma y se vuelve a la idea en discusión.'},
  quiz:[{q:'¿Qué hace la falacia ad hominem?',o:['Cita a un experto en el tema','Ataca a la persona en lugar de discutir su argumento','Presenta datos falsos','Compara dos casos parecidos'],a:1,e:'"Ad hominem" significa "contra la persona": desvía la discusión hacia quien habla.',lv:'L'},
   {q:'"Si dejamos salir cinco minutos antes, luego querrán salir una hora antes y al final nadie vendrá al colegio." ¿Qué falacia es?',o:['Falso dilema','Pendiente resbaladiza','Apelación a la mayoría','Ad hominem'],a:1,e:'Encadena consecuencias cada vez más graves sin probar que una lleve a la otra.',lv:'I'},
   {q:'En un debate, tu rival usa una falacia contra ti. ¿Cuál es la respuesta más sólida?',o:['Responder con otra falacia más fuerte','Nombrar el error con calma, mostrar por qué no prueba nada y volver a la idea en discusión','Retirarse del debate sin decir nada','Burlarse de su forma de hablar'],a:1,e:'Refutar una falacia es desmontar el razonamiento, no atacar a quien lo dijo.',lv:'C'}],
  tip:'Cierre con una réplica oral: cada estudiante elige una falacia del debate y graba con el celular (o dice en voz alta) una respuesta de un minuto que la nombre, explique el error y vuelva al tema con respeto.'},
 {id:'g11u2l3',title:'El ensayo argumentativo',time:50,std:'Produzco textos escritos que evidencian el conocimiento que he alcanzado acerca del funcionamiento de la lengua en situaciones de comunicación y el uso de las estrategias de producción textual.',dba:'DBA 8 (11°): produce textos académicos, como el ensayo, a partir de procedimientos sistemáticos de corrección lingüística y las reglas de producción textual.',
  body:['El <b>ensayo argumentativo</b> defiende una <b>tesis</b> con razones. En la <b>introducción</b> presentas el tema y la tesis. En el <b>desarrollo</b>, cada párrafo sostiene un argumento.',
   'En la <b>conclusión</b> retomas la tesis sin repetirla palabra por palabra y la proyectas hacia el futuro. Al final van las <b>referencias</b>, las fuentes que usaste.',
   'Cada párrafo del desarrollo sigue un orden: idea principal, argumento que la sostiene, evidencia o cita, y un cierre que la conecta con la tesis.',
   'Un buen ensayo reconoce el <b>contraargumento</b>, la mejor razón del otro lado, y lo <b>refuta</b>: le responde con razones. Suele ir después de los argumentos y antes de la conclusión. Así muestras que conoces la otra postura y aun así sostienes tu tesis.',
   'Los <b>conectores</b> guían al lector. <b>Orden</b>: <i>en primer lugar, en segundo lugar</i>. <b>Adición</b>, para sumar una razón en la misma dirección: <i>además, también</i>. <b>Oposición</b>, para una idea contraria o para refutar: <i>pero, sin embargo, no obstante, en cambio, aunque</i>.',
   'Más conectores. <b>Consecuencia</b>: <i>por eso, por lo tanto, por consiguiente, en consecuencia, así que</i>. <b>Ejemplo</b>: <i>por ejemplo</i>. <b>Explicación</b>: <i>es decir</i>. <b>Cierre</b>: <i>en conclusión</i>.',
   'Las ideas ajenas se <b>citan</b>. En <b>APA</b> (7.ª edición) la cita lleva autor y año: (UNESCO, 2023). La referencia de un libro va así: Apellido, Inicial. (Año). <i>Título en cursiva</i>. Editorial. Las referencias van en orden alfabético.'],
  bites:[{ej:'Tesis sobre la IA: "El colegio debe enseñar a usar la inteligencia artificial en lugar de prohibirla".',check:{q:'¿Dónde se presenta la tesis?',o:['En la introducción','En las referencias'],a:0,e:'La introducción presenta el tema y la tesis.'}},
   {ej:'"En conclusión, la escuela necesita reglas claras para la IA, no prohibiciones."',ojo:'No copies la tesis igualita en la conclusión: dila de otra forma.'},
   {ej:'Idea: prohibir la IA no sirve. Argumento: igual se usa a escondidas. Evidencia: la UNESCO (2023) pide formar criterio. Cierre: por eso hay que enseñarla.',check:{q:'¿Qué va al final de un párrafo del desarrollo?',o:['Un cierre que lo conecta con la tesis','La lista de referencias'],a:0,e:'Idea, argumento, evidencia y cierre.'}},
   {ej:'"Hay quienes temen que la IA nos haga dejar de pensar; sin embargo, eso depende de cómo se use."',check:{q:'¿Por qué conviene refutar el contraargumento?',o:['Muestra que conoces la otra postura y aun así sostienes la tuya','Hace el ensayo más largo'],a:0,e:'Anticipar la objeción muestra rigor.'}},
   {ej:'"La IA ayuda a redactar; <b>sin embargo</b>, a veces inventa datos." "Da retroalimentación; <b>además</b>, ahorra tiempo."',ojo:'"Además" suma en la misma dirección; "sin embargo" va en contra.',check:{q:'¿Qué conector presenta una idea contraria?',o:['Además','Sin embargo','Por ejemplo'],a:1,e:'"Sin embargo" es de oposición.'}},
   {ej:'"Prohibir la IA no evita que se use; <b>por lo tanto</b>, es mejor enseñar reglas claras."',check:{q:'"Por consiguiente" es un conector de…',o:['Consecuencia','Ejemplo'],a:0,e:'Introduce lo que resulta de lo anterior.'}},
   {ej:'UNESCO. (2023). <i>Guía para la IA generativa en la educación y la investigación</i>.',ojo:'Citar da fuerza al texto y respeta el trabajo de otros; sin fuentes, el ensayo se cae.',check:{q:'¿Qué lleva una cita en APA dentro del texto?',o:['Autor y año','Solo el título'],a:0,e:'Por ejemplo: (UNESCO, 2023).'}}],
  key:'Tesis clara, tres argumentos, contraargumento refutado, conclusión y fuentes citadas en APA.',
  co:'Tema sugerido: ¿debe el colegio permitir la inteligencia artificial en las tareas? La UNESCO publicó en 2023 una guía sobre la IA generativa en la educación que sirve como fuente.',
  act:{type:'write',prompt:'Escribe un ensayo argumentativo sobre la inteligencia artificial en el colegio, con tesis, tres argumentos, un contraargumento refutado y al menos una cita en formato APA.',purpose:{q:'¿Qué postura vas a defender?',o:['La IA debe permitirse en las tareas, con reglas claras','La IA no debe permitirse en las tareas','Otra postura sobre la IA en el colegio']},plan:[{q:'Tu tesis en una oración',ph:'Ej.: El colegio debe enseñar a usar la IA en lugar de prohibirla.'},{q:'Argumento 1 (y su tipo)',ph:'Ej.: causa: prohibirla no evita que se use'},{q:'Argumento 2 (y su tipo)',ph:'Ej.: autoridad: la guía de la UNESCO (2023)'},{q:'Argumento 3 (y su tipo)',ph:'Ej.: ejemplo: un profesor que la usa para dar retroalimentación'},{q:'Contraargumento y cómo lo refutas',ph:'Ej.: "La IA hace que no pensemos"; sin embargo...'},{q:'Fuente que vas a citar (autor y año)',ph:'Ej.: UNESCO, 2023'}],min:250,checklist:['La tesis aparece clara en la introducción','Cada argumento tiene su propio párrafo','Presento un contraargumento y lo refuto','Uso conectores para unir ideas y párrafos','Cito al menos una fuente con (Autor, año) y la incluyo en las referencias en formato APA','La conclusión retoma la tesis sin repetirla palabra por palabra','Revisé ortografía, tildes y puntuación'],model:'En conclusión, prohibir la inteligencia artificial en las tareas sería como prohibir la calculadora en la clase de física: la herramienta seguiría en el bolsillo de cada estudiante. Como recomienda la UNESCO (2023), el reto de la escuela no es esconderla, sino enseñar a usarla con criterio, citarla con honestidad y verificar lo que produce. Referencias: UNESCO. (2023). <i>Guía para la IA generativa en la educación y la investigación</i>.'},
  quiz:[{q:'¿En qué parte del ensayo argumentativo se presenta la tesis?',o:['En la introducción','En las referencias','Solo en el título','Únicamente en la conclusión'],a:0,e:'La introducción presenta el tema y la tesis; la conclusión la retoma.',lv:'L'},
   {q:'Un párrafo empieza: "___, hay quienes piensan que la IA hará que los estudiantes dejen de pensar". ¿Qué conector encaja para presentar la postura contraria?',o:['Por lo tanto','En conclusión','Sin embargo','Por ejemplo'],a:2,e:'"Sin embargo" introduce una idea que se opone a lo anterior: aquí, el contraargumento.',lv:'I'},
   {q:'¿Por qué un ensayo es más convincente si reconoce y refuta el contraargumento?',o:['Porque se vuelve más largo','Porque muestra que el autor conoce la otra postura y aun así puede sostener su tesis','Porque confunde al lector','Porque así ya no necesita argumentos'],a:1,e:'Anticipar la objeción y responderla demuestra rigor y honestidad intelectual.',lv:'C'}],
  tip:'Haga una "subasta de contraargumentos": cada grupo lanza la mejor objeción a la tesis de otro grupo, que debe refutarla por escrito en cinco minutos.'}
]},
{id:'g11u3',title:'Hacia Saber 11',desc:'Textos filosóficos, medios y ciudadanía, y un simulacro integrador.',lessons:[
 {id:'g11u3l1',title:'Leer textos filosóficos',time:50,std:'Asumo una actitud crítica frente a los textos que leo y elaboro, y frente a otros tipos de texto: explicativos, descriptivos y narrativos.',dba:'DBA 6 (11°): comprende que los argumentos de sus interlocutores involucran procesos de comprensión, crítica y proposición.',
  body:['Un <b>texto filosófico</b> no cuenta una historia ni da instrucciones. Plantea un <b>problema</b>: una pregunta de fondo que no tiene respuesta obvia, como ¿qué es la libertad? o ¿podemos conocer la realidad?',
   'Luego defiende una <b>tesis</b>: la respuesta del autor al problema. Suele ser una afirmación general, como "la libertad exige hacerse responsable".',
   'La tesis se sostiene con <b>argumentos</b>, razones generales que explican por qué sería cierta, y con <b>ejemplos</b>, casos concretos que ilustran y apoyan una idea abstracta.',
   'Para leerlo, busca primero la pregunta, luego la tesis y después su apoyo. Palabras como <i>pero, en realidad, en el fondo, por eso</i> suelen anunciar la postura del autor. A veces la tesis se retoma al final.',
   'Así han trabajado los grandes filósofos. <b>Platón</b>, en <i>La República</i>, usa la alegoría de la caverna para explicar el paso de la ignorancia al conocimiento. <b>Aristóteles</b>, en la <i>Política</i>, define al ser humano como un "animal político" que vive en comunidad.',
   '<b>René Descartes</b>, en el <i>Discurso del método</i> (1637), busca algo de lo que no se pueda dudar y responde: "Pienso, luego existo". <b>Immanuel Kant</b>, en "¿Qué es la Ilustración?" (1784), le dio a esa época su lema: "¡Atrévete a saber!".',
   'El colombiano <b>Estanislao Zuleta</b> (Medellín, 1935-1990), en <i>Elogio de la dificultad</i>, se pregunta por qué soñamos con una vida sin obstáculos. Su tesis: desear la facilidad es renunciar a pensar y a crecer. Leer así es dialogar con el autor, no solo repetirlo.'],
  bites:[{ej:'"¿Sería mejor una vida sin problemas?" es una pregunta filosófica: no se responde buscando en Google.',check:{q:'En un texto filosófico, ¿qué es el problema?',o:['La pregunta de fondo','Un ejemplo de la vida diaria'],a:0,e:'El problema es la pregunta que mueve el texto.'}},
   {ej:'Problema: "¿Es justo obedecer una ley injusta?". Tesis: "Desobedecer una ley injusta puede ser un deber moral".',ojo:'Problema = pregunta. Tesis = respuesta. No los confundas.',check:{q:'¿Qué es la tesis?',o:['La respuesta o postura del autor','La pregunta de fondo'],a:0,e:'La tesis responde al problema.'}},
   {ej:'Ejemplo: "Un remo parece doblado dentro del agua aunque esté recto" apoya la tesis de que los sentidos pueden engañarnos.',check:{q:'¿Para qué sirve un ejemplo en un texto filosófico?',o:['Para ilustrar y apoyar una idea abstracta','Para plantear la pregunta'],a:0,e:'Hace concreta una idea general.'}},
   {ej:'"Muchos piensan que lo fácil es mejor. <b>Pero en realidad</b>, lo fácil no nos hace crecer." Después del "pero" viene la postura del autor.',check:{q:'¿Qué suele anunciar "pero en realidad..."?',o:['La postura del autor','Un dato numérico'],a:0,e:'Esos marcadores suelen introducir la tesis.'}},
   {ej:'En la caverna de Platón, unos prisioneros solo ven sombras y creen que son la realidad, hasta que uno sale a la luz.'},
   {ej:'Descartes dudó de todo, hasta de sus sentidos; lo único que no pudo dudar fue que estaba pensando.',check:{q:'"Pienso, luego existo" es de…',o:['Descartes','Kant','Platón'],a:0,e:'René Descartes, Discurso del método (1637).'}},
   {ej:'Zuleta: "Quien aprende a tocar guitarra no pide que desaparezcan las cuerdas".',ojo:'Dialogar con el autor es preguntarte si estás de acuerdo y por qué, no solo repetir su frase.',check:{q:'¿Con qué estaría en desacuerdo Zuleta?',o:['Aprender cuesta, y en eso está su valor','Una app que haga todas nuestras tareas sería lo ideal'],a:1,e:'Zuleta critica el deseo de que todo se nos dé hecho.'}}],
  key:'Problema: la pregunta de fondo. Tesis: la respuesta del autor. Argumentos y ejemplos: el apoyo.',
  co:'Estanislao Zuleta, nacido en Medellín, se formó de manera autodidacta y llegó a enseñar en universidades del país; "Elogio de la dificultad" es uno de los ensayos más leídos en los colegios de Colombia.',
  act:{type:'mark',prompt:'Texto a partir de las ideas de Zuleta. Elige un color y toca el problema, la tesis, el argumento y los ejemplos.',cats:[{n:'Problema',c:'#1F5FA8'},{n:'Tesis',c:'#C0453A'},{n:'Argumento',c:'#B06A10'},{n:'Ejemplo',c:'#2F7D32'}],text:'[[¿Por qué soñamos con una vida sin obstáculos?|0]] [[¿Es de verdad deseable un mundo donde todo se nos dé hecho?|0]] Muchas utopías prometen eso: abundancia sin trabajo, amor sin conflicto, verdad sin búsqueda. [[Pero desear que todo sea fácil es desear, en el fondo, dejar de pensar.|1]] [[Solo ante lo que se nos resiste nos vemos obligados a crear algo nuevo.|2]] [[Quien aprende a tocar guitarra no pide que desaparezcan las cuerdas;|3]] [[quien abandona un libro difícil en la primera página se pierde lo que ese libro podía cambiar en él.|3]] [[Por eso, en lugar de elogiar la facilidad, conviene aprender a amar la dificultad.|1]]',e:'El texto abre con preguntas (el problema), responde con una tesis que retoma al final y la sostiene con un argumento y dos ejemplos.'},
  quiz:[{q:'En un texto filosófico, ¿qué es la tesis?',o:['La pregunta de fondo','La respuesta o postura que defiende el autor','Un ejemplo de la vida diaria','El título del texto'],a:1,e:'El problema es la pregunta; la tesis, la respuesta que el autor defiende.',lv:'L'},
   {q:'"Quien aprende a tocar guitarra no pide que desaparezcan las cuerdas." ¿Qué función cumple esta frase en el texto de la actividad?',o:['Plantea el problema','Es la tesis','Es un ejemplo que apoya la tesis','Es un contraargumento'],a:2,e:'Muestra con un caso concreto que la dificultad es parte de lo que se aprende.',lv:'I'},
   {q:'¿Con cuál de estas afirmaciones estaría en desacuerdo Zuleta?',o:['Aprender cuesta, y en eso está su valor','Lo ideal sería una aplicación que haga todas nuestras tareas por nosotros','Los problemas nos obligan a crear','Un libro difícil puede transformarnos'],a:1,e:'Esperar que todo se nos dé hecho es justo el deseo de facilidad que Zuleta critica.',lv:'C'}],
  tip:'Antes de leer, abra un conversatorio con una pregunta cotidiana ("¿sería mejor una vida sin problemas?"); después comparen sus respuestas con la tesis de Zuleta.'},
 {id:'g11u3l2',title:'Medios, poder y ciudadanía',time:50,std:'Interpreto en forma crítica la información difundida por los medios de comunicación masiva.',dba:'DBA 1 y 2 (11°): asume una posición crítica frente a los elementos ideológicos presentes en los medios de comunicación; expresa con sentido crítico cómo se articulan los códigos verbales y no verbales.',
  body:['Los medios no solo informan. Al elegir qué contar, qué palabras usar, a quién citar y qué foto poner, construyen un <b>enfoque</b> o <b>encuadre</b>. La misma marcha puede ser "una jornada histórica" o "un caos de vándalos".',
   'Para leer críticamente, compara varias versiones y separa: los <b>hechos verificables</b> (cifras, lugares, horas), las <b>palabras valorativas</b> (adjetivos y verbos cargados), las <b>fuentes</b> (¿a quién le dan la voz?) y lo que se <b>omite</b>.',
   'Informar con sesgo no siempre es mentir, pero puede <b>manipular</b>. Distingue la <b>información</b>, que presenta hechos verificables, de la <b>opinión</b>, que los valora.',
   'Un ciudadano crítico contrasta medios y averigua quién es el dueño de cada uno: sus intereses pueden influir en el enfoque. Recuerda que mucha gente solo lee el titular y que una noticia muy compartida no está, por eso, verificada.',
   'Al evaluar una publicación, decide si es confiable, engañosa o falsa. Es <b>confiable</b> si tiene una fuente identificable u oficial, datos precisos que se pueden comprobar y varias voces.',
   'Es <b>engañosa</b> si parte de un hecho real pero lo deforma: un titular que exagera lo que dice el cuerpo, palabras cargadas, una sola voz o una foto real sacada de contexto, de otra fecha o lugar.',
   'Es <b>falsa</b> si es un invento: no tiene fuente ni fecha, cita estudios que no aparecen en ninguna parte o es una cadena que pide reenviar "antes de que lo borren".'],
  bites:[{ej:'Una marcha por la carrera Séptima de Bogotá: un medio dice "Miles marchan por la educación" y otro "Vándalos paralizan la ciudad".',check:{q:'¿Qué es el enfoque de una noticia?',o:['La forma en que el medio elige contar el hecho','La hora del hecho'],a:0,e:'Las palabras, fuentes y fotos que elige construyen el enfoque.'}},
   {ej:'Dato: "unas 15.000 personas, según la Secretaría de Gobierno". Valorativa: "vándalos", "heroica". Fuente: "denunció un comerciante en redes".',ojo:'Las palabras valorativas no describen: juzgan.',check:{q:'¿Cuál es una palabra valorativa?',o:['"Vándalos"','"15.000 personas"','"jueves"'],a:0,e:'"Vándalos" juzga a las personas; no es un dato.'}},
   {ej:'Información: "La marcha terminó a las 5:00 p. m.". Opinión: "Fue la marcha más bonita de la historia".',check:{q:'"Omitir un dato importante" es…',o:['Una forma de sesgo','Siempre neutral'],a:0,e:'Lo que se calla también construye el enfoque.'}},
   {ej:'Si un video tiene un millón de vistas, igual puede ser falso: viralidad no es verificación.',ojo:'Lee más allá del titular antes de compartir.'},
   {ej:'"TransMilenio cerrará tres estaciones de la Séptima de 2:00 a 6:00 p. m.", publicado por la cuenta oficial de TransMilenio.',check:{q:'¿Qué hace confiable una publicación?',o:['Fuente oficial y datos que se pueden comprobar','Muchos emojis y mayúsculas'],a:0,e:'Fuente identificable, datos precisos y varias voces.'}},
   {ej:'Titular: "Caos total: la ciudad colapsa". Cuerpo: "la movilidad se afectó 40 minutos en dos calles". O una foto real de 2019 presentada como de ayer.',check:{q:'Una foto real, pero de otra fecha, presentada como de hoy es…',o:['Engañosa','Confiable'],a:0,e:'Parte de algo real, pero lo saca de contexto.'}},
   {ej:'Cadena de WhatsApp: "El Gobierno eliminará Saber 11. ¡Reenvía antes de que lo borren!". El ICFES no dice nada.',ojo:'Si no hay fuente ni fecha, desconfía.',check:{q:'Un "estudio" que no aparece en ninguna universidad ni revista hace que la noticia sea…',o:['Falsa','Confiable'],a:0,e:'El estudio no existe: es un invento.'}}],
  key:'Mismo hecho, distintos enfoques: separa datos, palabras valorativas y fuentes, y compara antes de creer.',
  co:'Una marcha estudiantil por la carrera Séptima de Bogotá puede aparecer en tres medios con cifras, fotos y protagonistas distintos: comparar las coberturas es la mejor forma de acercarse a lo que pasó.',
  act:{type:'fix',prompt:'Esta nota usa palabras valorativas. Toca cada palabra cargada y cámbiala por una neutra.',text:'Unas 15.000 {{personas|hordas}} {{marcharon|irrumpieron}} el jueves por la carrera Séptima, según la Secretaría de Gobierno. Pedían más presupuesto para la universidad pública. La movilidad se {{afectó|destruyó}} durante dos horas y la marcha {{terminó|degeneró}} a las 5:00 p. m. en la Plaza de Bolívar.',e:'Una nota informativa usa palabras neutras y deja que los datos hablen.'},
  quiz:[{q:'Según la lección, ¿qué es una palabra valorativa?',o:['Una cifra oficial','Un adjetivo o verbo que expresa un juicio sobre el hecho','El nombre de la fuente','La hora del evento'],a:1,e:'Palabras como "vándalos" o "histórica" no describen: juzgan.',lv:'L'},
   {q:'Un medio titula "Vándalos paralizan la ciudad" y otro "Miles marchan por la educación". ¿Qué se puede inferir?',o:['Que hubo dos marchas distintas','Que los dos medios enfocan el mismo hecho desde posturas diferentes','Que uno de los dos inventó la marcha','Que los dos son neutrales'],a:1,e:'El hecho es el mismo; cambian las palabras, los protagonistas y la valoración.',lv:'I'},
   {q:'¿Cuál es la forma más sólida de formarse una opinión sobre una marcha?',o:['Leer solo el medio que coincide con lo que pienso','Comparar varias fuentes, separar hechos de valoraciones y buscar datos verificables','Creer el video que tenga más vistas','Esperar a que alguien lo explique en un meme'],a:1,e:'Contrastar fuentes y separar datos de opiniones reduce el efecto del encuadre.',lv:'C'}],
  tip:'Lleve impresas tres coberturas reales de un mismo hecho reciente y pida a los grupos subrayar con colores los datos, las valoraciones y las fuentes; luego comparen qué omite cada una.'},
 {id:'g11u3l3',title:'Simulacro integrador',time:50,std:'Elaboro hipótesis de interpretación atendiendo a la intención comunicativa y al sentido global del texto que leo.',dba:'DBA 6 (11°): comprende que los argumentos de sus interlocutores involucran procesos de comprensión, crítica y proposición.',
  body:['La prueba de <b>Lectura Crítica</b> de Saber 11 evalúa tres competencias. Cada una corresponde a uno de los tres niveles de lectura: <b>literal</b>, <b>inferencial</b> y <b>crítico</b>.',
   '<b>Identificar y entender</b> lo que dice el texto es el nivel literal ("según el texto, ¿en qué año...?"). <b>Comprender cómo se articulan sus partes</b> para darle un sentido global es el nivel inferencial ("¿qué función cumple el segundo párrafo?").',
   '<b>Reflexionar a partir del texto y evaluar</b> su contenido, la intención y la postura del autor es el nivel crítico ("¿por qué el autor usa la palabra imperdonable?").',
   'La prueba trae <b>textos continuos</b>, escritos en párrafos (cuentos, ensayos, columnas), y <b>discontinuos</b>, con tablas, gráficos, íconos o viñetas (infografías, cómics, avisos). En un discontinuo, lee primero el título, los encabezados, las convenciones y las unidades; después, las cifras.',
   'Separa tres cosas. Un <b>dato</b> es información verificable que el texto dice directamente. Una <b>conclusión</b> deduce algo a partir de los datos ("todo indica que", "entonces", "por eso"). Una <b>opinión</b> valora los hechos ("imperdonable", "el más valioso") y muestra la postura del autor.',
   'Las preguntas son de <b>selección múltiple con única respuesta</b>: cuatro opciones (A, B, C y D) y solo una correcta. Estrategia: lee primero la pregunta y vuelve al texto a buscar la <b>evidencia</b>.',
   'Descarta las opciones que dicen más (exageran o generalizan), menos o algo distinto de lo que dice el texto. Usa lo del grado: palabras valorativas, fuentes y conectores como <i>pero, por eso, en conclusión</i>, que anuncian la tesis o la conclusión.'],
  bites:[{ej:'Los cuadernillos que publica el ICFES muestran el formato real de la prueba.',check:{q:'¿Cuántas competencias evalúa Lectura Crítica?',o:['Tres','Diez'],a:0,e:'Tres, una por cada nivel de lectura.'}},
   {ej:'Literal: "Según el texto, ¿cuántos libros se prestaron en 2024?". Inferencial: "¿Qué relación hay entre el cierre y la caída de préstamos?".',check:{q:'"¿Qué función cumple el segundo párrafo?" es de nivel…',o:['Literal','Inferencial'],a:1,e:'Pregunta cómo se relacionan las partes del texto.'}},
   {ej:'"Recortar el presupuesto sería un error imperdonable." Pregunta crítica: "¿qué postura muestra el autor con esa palabra?".',ojo:'Crítico no es "lo que yo opino sin leer": es evaluar el texto con razones.'},
   {ej:'Tabla: "Préstamos de libros por año: 2019: 52.000 · 2020: 9.000 · 2024: 61.000". Primero lee el título y las unidades: son libros prestados por año.',check:{q:'¿Qué es un cómic?',o:['Un texto discontinuo','Un texto continuo'],a:0,e:'Combina viñetas, imágenes y texto.'}},
   {ej:'Dato: "En 2024 se prestaron 61.000 libros". Conclusión: "Todo indica que los jóvenes volvieron gracias a los clubes". Opinión: "Recortar el presupuesto sería un error imperdonable".',check:{q:'"Todo indica que los jóvenes volvieron a la biblioteca." ¿Qué es?',o:['Un dato','Una conclusión','Una opinión'],a:1,e:'"Todo indica que" anuncia una conclusión.'}},
   {ej:'Pregunta: "¿Cuántos libros se prestaron en 2020?". Vuelves a la tabla y encuentras la evidencia: 9.000.',check:{q:'¿Dónde está la mejor evidencia para responder?',o:['En el texto','En lo que yo opino'],a:0,e:'Toda respuesta se apoya en el texto.'}},
   {ej:'Opción trampa: "Los préstamos subieron todos los años". Falso: en 2020 bajaron. Otra trampa: "En 2024 se prestó el doble": 61.000 no es el doble de 52.000.',ojo:'Palabras como "siempre", "todos" o "nunca" suelen delatar una opción que exagera.',check:{q:'Una opción dice más de lo que dice el texto. ¿Qué haces?',o:['La descarto','La elijo'],a:0,e:'Las opciones que exageran o generalizan se descartan.'}}],
  key:'Identificar, comprender el sentido global y evaluar: siempre con la evidencia del texto.',
  co:'Los cuadernillos de preguntas que publica el ICFES muestran el formato real: cada pregunta tiene cuatro opciones (A, B, C y D) y solo una es correcta.',
  act:{type:'choose',prompt:'Mini simulacro. Lee cada situación y elige la respuesta.',items:[{s:'TABLA. Préstamos de libros por año: 2019: 52.000 · 2020: 9.000 · 2024: 61.000. ¿Qué dice la tabla sobre 2024?',o:['Se prestó el doble que en 2019','Se prestaron 61.000 libros','La biblioteca cerró'],a:1,e:'Es un dato literal: 61.000 libros. No es el doble de 52.000.'},{s:'"En 2020 la biblioteca cerró durante siete meses." ¿Qué es esta frase?',o:['Un dato','Una conclusión','Una opinión'],a:0,e:'Es información verificable que el texto dice directamente.'},{s:'"Todo indica que los jóvenes volvieron a la biblioteca gracias a los clubes de lectura." ¿Qué es esta frase?',o:['Un dato','Una conclusión','Una opinión'],a:1,e:'Va más allá de los datos y deduce algo: "todo indica que" la anuncia.'},{s:'"Recortar el presupuesto de la biblioteca sería un error imperdonable." ¿Qué es esta frase?',o:['Un dato','Una conclusión','Una opinión'],a:2,e:'"Imperdonable" valora: es la postura del autor.'},{s:'Pregunta: "¿Por qué el autor usa la palabra imperdonable?". ¿De qué nivel es?',o:['Literal','Inferencial','Crítico'],a:2,e:'Evalúa la intención y la postura del autor: nivel crítico.'},{s:'Una opción de respuesta dice: "Los préstamos subieron todos los años". ¿Qué haces con ella?',o:['La elijo porque suena bien','La descarto: en 2020 los préstamos bajaron','La elijo porque es la más larga'],a:1,e:'Dice algo distinto de lo que muestra la tabla: se descarta.'},{s:'Una infografía sobre el agua de Bogotá, con íconos y cifras. ¿Qué tipo de texto es?',o:['Continuo','Discontinuo'],a:1,e:'Organiza la información en gráficos e íconos: es discontinuo.'}],e:'Primero la pregunta, luego la evidencia en el texto, y descarta lo que exagera o dice otra cosa.'},
  quiz:[{q:'Según la lección, ¿cuál de estos es un texto discontinuo?',o:['Un cuento','Una columna de opinión','Una infografía','Un fragmento filosófico'],a:2,e:'Los textos discontinuos organizan la información en tablas, gráficos o esquemas.',lv:'L'},
   {q:'En la tabla, los préstamos pasan de 52.000 (2019) a 9.000 (2020) y a 61.000 (2024). ¿Qué conclusión está mejor sustentada?',o:['La biblioteca cerró para siempre en 2020','Los préstamos cayeron en 2020 y en 2024 superaron el nivel de 2019','En 2024 se prestó el doble que en 2019','Los préstamos bajaron todos los años'],a:1,e:'61.000 es más que 52.000, pero no el doble; la caída de 2020 fue temporal.',lv:'I'},
   {q:'El autor afirma que recortar el presupuesto "sería un error imperdonable". ¿Qué se puede decir de esa frase?',o:['Es un dato de la tabla','Es una opinión que expresa la postura del autor','Es la cita de una autoridad','Es un hecho comprobado'],a:1,e:'"Imperdonable" es una valoración: expresa la postura del autor, no un dato.',lv:'C'}],
  tip:'Haga el simulacro con tiempo real (cerca de dos minutos por pregunta). Al final, cada estudiante cuenta sus aciertos en preguntas literales, inferenciales y críticas: ese es su informe por nivel y le dice qué reforzar.'}
]}
]};
export default grade;
